(function(){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cents=n=>Math.round((n+Number.EPSILON)*100)/100, money=n=>'PKR '+Number(n).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
function calculate({base,sale,commission,rate,points=null,policy='reserve'}){
 const pool=cents(base*commission),company=cents(base*.05),introducer=cents(pool*.10),budget=cents(pool-company-introducer-cents(base-sale));
 const maximum=Math.floor((budget/rate+1e-10)*10000)/10000,assigned=points===null?maximum:points,funding=Math.ceil((assigned*rate-1e-9)*100)/100;
 const remainder=cents(budget-funding),discount=policy==='discount'?remainder:0;
 const valid=[base,sale,commission,rate,assigned].every(Number.isFinite)&&base>0&&sale>0&&sale<=base&&commission>=0&&commission<=1&&rate>0&&budget>=0&&assigned>=0&&assigned<=maximum&&sale-discount>0;
 return {pool,company,introducer,budget,maximum,assigned,reserve:policy==='reserve'?remainder:0,discount,finalPrice:cents(sale-discount),valid};
}
function form(p,v,rate){if(p.bundle_definition)return '<p class="helper">Bundle pricing uses its included products. Open Bundles to edit its PPV and discount.</p>';
 const proposal=p.product_commission_proposals,pending=proposal?.status==='pending',commission=pending?proposal.requested_rate:p.commission_rate_override,points=pending?null:p.assigned_ppv;
 const sale=Number(p.price_pkr)+Number(p.reward_discount_pkr||0),base=Number(p.vendor_submitted_price_pkr??p.price_pkr);
 return `<section class="economics-editor"><header><div><small>PRODUCT SETTINGS</small><h3>Price, commission & PPV</h3></div><span>Vendor default: ${(Number(v.commission_rate)*100).toFixed(2)}%</span></header>${proposal?`<p class="helper commission-proposal-note">Seller proposed: <strong>${proposal.requested_rate==null?'Vendor default':(Number(proposal.requested_rate)*100).toFixed(4).replace(/0+$/,'').replace(/\.$/,'')+'%'}</strong> · ${pending?'Awaiting review. Approve & publish saves the settings below together.':'Reviewed — final approved settings are shown below.'}</p>`:''}<form class="product-economics-form" data-product="${esc(p.id)}" data-submission="${esc(proposal?.submitted_at||'')}" data-base="${base}" data-default="${Number(v.commission_rate)}" data-rate="${rate}"><div class="economics-fields"><label>Sale price before PPV discount (PKR)<input name="sale" type="number" step="0.01" min="0.01" max="${base}" value="${sale}" required></label><label>Crossed-out price (optional)<input name="compare" type="number" step="0.01" min="0.01" value="${p.compare_at_price_pkr??''}" placeholder="Original retail price"></label><label>Specific percentage for this product (%)<input name="commission" type="number" min="0" max="100" step="0.0001" value="${commission==null?'':Number((Number(commission)*100).toFixed(4))}" placeholder="Vendor default ${(Number(v.commission_rate)*100).toFixed(2)}%"><small>Leave blank to use the vendor agreement.</small></label><label>Assigned PPV<input name="points" type="number" min="0" step="0.0001" value="${points??''}" placeholder="Auto: maximum PPV"><small>Leave blank to use the calculated maximum.</small></label><label class="economics-remainder">When Assigned PPV is below maximum<select name="remainder"><option value="reserve" ${p.ppv_remainder_policy!=='discount'?'selected':''}>Hold remaining budget for reconciliation</option><option value="discount" ${p.ppv_remainder_policy==='discount'?'selected':''}>Give remaining budget as customer discount</option></select></label></div><div class="economics-preview" aria-live="polite"></div><div class="economics-actions"><span role="status"></span><button class="btn primary" type="submit">Save product settings</button></div></form></section>`;
}
function preview(f){const r=calculate({base:Number(f.dataset.base),sale:Number(f.elements.sale.value),commission:f.elements.commission.value===''?Number(f.dataset.default):Number((Number(f.elements.commission.value)/100).toFixed(6)),rate:Number(f.dataset.rate),points:f.elements.points.value===''?null:Number(f.elements.points.value),policy:f.elements.remainder.value});
 const approval=f.closest('.admin-product-record')?.querySelector('.approval-ppv');if(approval)approval.value=r.valid?r.assigned:'';
 f.elements.points.max=Math.max(0,r.maximum);f.querySelector('[type=submit]').disabled=!r.valid;
 f.querySelector('.economics-preview').innerHTML=r.valid?`<dl><div><dt>Company fee · 5% of product price</dt><dd>${money(r.company)}</dd></div><div><dt>Vendor introducer · 10% of commission</dt><dd>${money(r.introducer)}</dd></div><div><dt>Maximum PPV</dt><dd>${r.maximum.toFixed(4)}</dd></div><div><dt>Assigned PPV</dt><dd>${r.assigned.toFixed(4)}</dd></div><div><dt>${f.elements.remainder.value==='discount'?'Additional customer discount':'Reconciliation reserve'}</dt><dd>${money(f.elements.remainder.value==='discount'?r.discount:r.reserve)}</dd></div><div class="economics-final"><dt>Customer pays</dt><dd>${money(r.finalPrice)}</dd></div></dl>`:'<p class="economics-error">Check the commission, sale price and assigned PPV. The commission must cover fees and discounts; PPV cannot exceed its maximum.</p>';return r;
}
function approvalPayload(f){if(!f.reportValidity()||!preview(f).valid)throw Error('Check the product percentage, price and PPV before approval');return {p_product:f.dataset.product,p_sale:Number(f.elements.sale.value),p_compare:f.elements.compare.value===''?null:Number(f.elements.compare.value),p_commission:f.elements.commission.value===''?null:Number((Number(f.elements.commission.value)/100).toFixed(6)),p_ppv:f.elements.points.value===''?null:Number(f.elements.points.value),p_remainder:f.elements.remainder.value,p_submission:f.dataset.submission||null};}
function mount(api){document.addEventListener('input',e=>{const f=e.target.closest('.product-economics-form');if(f)preview(f)});document.addEventListener('change',e=>{const f=e.target.closest('.product-economics-form');if(f)preview(f)});document.addEventListener('submit',async e=>{const f=e.target.closest('.product-economics-form');if(!f)return;e.preventDefault();if(f.dataset.busy==='1'||!preview(f).valid)return;f.dataset.busy='1';const button=f.querySelector('[type=submit]'),status=f.querySelector('[role=status]');button.disabled=true;status.textContent='Saving…';try{const {error}=await api.db.rpc('admin_save_product_economics',{p_product:f.dataset.product,p_sale:Number(f.elements.sale.value),p_compare:f.elements.compare.value===''?null:Number(f.elements.compare.value),p_commission:f.elements.commission.value===''?null:Number((Number(f.elements.commission.value)/100).toFixed(6)),p_ppv:f.elements.points.value===''?null:Number(f.elements.points.value),p_remainder:f.elements.remainder.value});if(error)throw error;status.textContent='Product settings saved';api.toast('Product settings saved');await api.reload()}catch(error){status.textContent=error.message;api.toast(error.message)}finally{f.dataset.busy='0';button.disabled=false}})}
window.MioProductEconomics={calculate,form,preview,mount,approvalPayload};
})();
